"""Shared configuration for braindump CLI."""

from __future__ import annotations

import hashlib
from pathlib import Path
from typing import Any

DEFAULT_MODEL = "gateway/anthropic:claude-sonnet-4-5"
DEFAULT_EMBEDDING_MODEL = "gateway/openai:text-embedding-3-small"

_model_name: str = DEFAULT_MODEL
_embedding_model_name: str = DEFAULT_EMBEDDING_MODEL


def configure_models(model: str | None = None, embedding_model: str | None = None) -> None:
    """Set the model names used by make_model/make_embedding_model."""
    global _model_name, _embedding_model_name
    if model:
        _model_name = model
    if embedding_model:
        _embedding_model_name = embedding_model


def init_env() -> None:
    """Load .env and configure logfire. Must be called before importing pydantic_ai."""
    from dotenv import load_dotenv

    load_dotenv()

    import logfire

    logfire.configure(send_to_logfire="if-token-present", console=False)
    logfire.instrument_pydantic_ai()
    logfire.instrument_httpx(capture_all=True)


def make_retry_client():
    """Create an httpx AsyncClient with retry transport for rate limits."""
    from httpx import AsyncClient, HTTPStatusError
    from pydantic_ai.retries import AsyncTenacityTransport, RetryConfig, wait_retry_after
    from tenacity import retry_if_exception_type, stop_after_attempt, wait_exponential

    return AsyncClient(
        transport=AsyncTenacityTransport(
            config=RetryConfig(
                retry=retry_if_exception_type((HTTPStatusError, ConnectionError)),
                wait=wait_retry_after(fallback_strategy=wait_exponential(multiplier=1, max=60)),
                stop=stop_after_attempt(5),
                reraise=True,
            ),
            validate_response=lambda r: r.raise_for_status(),
        ),
    )


def _retry_provider_factory(provider: str) -> Any:
    """Create a provider with retry HTTP client, similar to pydantic_ai's infer_provider."""
    http_client = make_retry_client()
    if provider.startswith("gateway/"):
        from pydantic_ai.providers.gateway import gateway_provider

        return gateway_provider(provider.removeprefix("gateway/"), http_client=http_client)  # type: ignore[arg-type]
    elif provider in ("google-vertex", "google-gla"):
        from pydantic_ai.providers.google import GoogleProvider

        return GoogleProvider(vertexai=provider == "google-vertex", http_client=http_client)
    else:
        from pydantic_ai.providers import infer_provider_class

        return infer_provider_class(provider)(http_client=http_client)  # type: ignore[call-arg]


def make_model():
    """Create a pydantic_ai Model from the configured model name, with retry HTTP client."""
    from pydantic_ai.models import infer_model

    return infer_model(_model_name, provider_factory=_retry_provider_factory)


def make_embedding_model():
    """Create a pydantic_ai EmbeddingModel from the configured name, with retry HTTP client."""
    from pydantic_ai.embeddings import infer_embedding_model

    return infer_embedding_model(_embedding_model_name, provider_factory=_retry_provider_factory)


def compute_file_hash(path: Path) -> str:
    """Compute SHA-256 hash of a file's contents."""
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(8192), b""):
            h.update(chunk)
    return h.hexdigest()


def compute_multi_file_hash(paths: list[Path]) -> str:
    """Compute SHA-256 hash over multiple files (sorted by name for stability)."""
    h = hashlib.sha256()
    for path in sorted(paths, key=lambda p: p.name):
        with open(path, "rb") as f:
            for chunk in iter(lambda: f.read(8192), b""):
                h.update(chunk)
    return h.hexdigest()


class RepoConfig:
    """Resolves all data paths from a repo string (owner/repo)."""

    def __init__(self, repo: str) -> None:
        self.repo = repo
        # Find project root (where pyproject.toml lives)
        self._root = Path(__file__).resolve().parent.parent.parent
        self.data_dir = self._root / "data" / repo

    def stage_dir(self, stage: str) -> Path:
        return self.data_dir / stage

    @property
    def pr_data_dir(self) -> Path:
        return self.stage_dir("1-download")

    @property
    def review_comments_dir(self) -> Path:
        return self.pr_data_dir / "review_comments"

    @property
    def extractions_path(self) -> Path:
        return self.stage_dir("2-extract") / "extractions.jsonl"

    @property
    def rules_path(self) -> Path:
        return self.stage_dir("3-synthesize") / "rules.jsonl"

    @property
    def rules_deduped_path(self) -> Path:
        return self.stage_dir("4-dedupe") / "rules.jsonl"

    @property
    def overrides_path(self) -> Path:
        return self.data_dir / "rule_overrides.jsonl"

    @property
    def placements_path(self) -> Path:
        return self.stage_dir("5-place") / "placements.jsonl"

    @property
    def organization_path(self) -> Path:
        return self.stage_dir("6-group") / "organized_rules.json"

    @property
    def output_dir(self) -> Path:
        return self.stage_dir("7-generate")

"""Shared Rich progress utilities for braindump pipeline stages."""

from __future__ import annotations

import json
from collections.abc import Generator
from contextlib import contextmanager
from dataclasses import dataclass, field
from decimal import Decimal
from pathlib import Path
from typing import Any

from rich.console import Console
from rich.panel import Panel
from rich.progress import (
    BarColumn,
    MofNCompleteColumn,
    Progress,
    ProgressColumn,
    SpinnerColumn,
    Task,
    TextColumn,
    TimeElapsedColumn,
)
from rich.text import Text

console = Console()


def format_cost(cost: Decimal) -> str:
    """Format a cost value for display."""
    if cost <= 0:
        return ""
    if cost < Decimal("0.01"):
        # Show enough precision for sub-cent values
        return f"${cost:.4f}"
    return f"${cost:.2f}"


def get_result_cost(result: Any) -> Decimal:
    """Extract total price from a PydanticAI agent run result."""
    try:
        cost_info = result.response.cost()
        if cost_info and cost_info.total_price is not None:
            return cost_info.total_price
    except Exception:
        pass
    return Decimal(0)


def save_stage_cost(cost_path: Path, cost: Decimal) -> None:
    """Persist stage cost to disk as JSON."""
    if cost > 0:
        cost_path.parent.mkdir(parents=True, exist_ok=True)
        with open(cost_path, "w") as f:
            json.dump({"cost": str(cost)}, f)


def load_stage_cost(cost_path: Path) -> Decimal:
    """Load persisted stage cost from disk."""
    if not cost_path.exists():
        return Decimal(0)
    try:
        with open(cost_path) as f:
            data = json.load(f)
        return Decimal(data["cost"])
    except Exception:
        return Decimal(0)


class CostColumn(ProgressColumn):
    """Renders accumulated stage cost from task fields."""

    def render(self, task: Task) -> Text:
        cost = task.fields.get("cost", "")
        if not cost:
            return Text("")
        return Text(cost, style="dim cyan")


@dataclass
class StageStats:
    """Accumulate metrics during a pipeline stage."""

    _data: dict[str, int | float | str] = field(default_factory=dict)
    detail: str | None = None
    _cost: Decimal = field(default_factory=lambda: Decimal(0))

    def set(self, key: str, value: int | float | str) -> None:
        self._data[key] = value

    def inc(self, key: str, amount: int = 1) -> None:
        self._data[key] = self._data.get(key, 0) + amount  # type: ignore[operator]

    def get(self, key: str, default: int | float | str = 0) -> int | float | str:
        return self._data.get(key, default)

    def summary(self) -> str:
        return " | ".join(f"{k}: {v}" for k, v in self._data.items())

    def as_dict(self) -> dict[str, int | float | str]:
        return dict(self._data)

    def add_cost(self, cost: Decimal) -> None:
        self._cost += cost

    @property
    def total_cost(self) -> Decimal:
        return self._cost


def make_progress() -> Progress:
    """Factory for a Progress bar with consistent columns."""
    return Progress(
        SpinnerColumn(),
        TextColumn("[progress.description]{task.description}"),
        BarColumn(bar_width=None),
        MofNCompleteColumn(),
        TimeElapsedColumn(),
        CostColumn(),
        console=console,
    )


@contextmanager
def stage_progress(
    stage_name: str,
    *,
    is_pipeline: bool = False,
    cost_path: Path | None = None,
) -> Generator[tuple[Progress, StageStats], None, None]:
    """Context manager that yields (Progress, StageStats).

    Prints a stage header on entry and a compact stats summary on exit.
    If cost_path is provided, persists accumulated cost to disk on exit.
    """
    if not is_pipeline:
        console.print(f"\n[bold]{stage_name}[/bold]")
    # When is_pipeline=True, run.py prints the header before calling _run()

    stats = StageStats()
    progress = make_progress()
    with progress:
        yield progress, stats

    # Persist cost to disk for status command
    if cost_path:
        save_stage_cost(cost_path, stats.total_cost)

    detail = stats.detail or (stats.summary() if stats._data else None)
    if detail:
        cost_str = format_cost(stats.total_cost)
        if cost_str:
            detail = f"{detail} | {cost_str}"
        console.print(f"  [dim]{detail}[/dim]")


def print_pipeline_header(stages: list[str], repo: str) -> None:
    """Print a styled panel at pipeline start."""
    arrow = " \u2192 "
    content = f"[bold]Pipeline:[/bold] {arrow.join(stages)}\n[bold]Repo:[/bold] {repo}"
    console.print(Panel(content, title="[bold]braindump[/bold]", expand=True))
    console.print()

"""Lookup tool for rule provenance.

Traces a rule ID back through all pipeline stages to the original comments.
"""

from __future__ import annotations

import json
from pathlib import Path

import typer

from braindump.config import RepoConfig

# ============================================================================
# Data Loading
# ============================================================================


def _load_comments(data_dir: Path) -> dict[int, dict]:
    """Load review comments from raw PR data, indexed by comment ID."""
    comments = {}
    review_dir = data_dir / "1-download" / "review_comments"
    if not review_dir.exists():
        return comments
    for path in review_dir.glob("*.json"):
        pr_number = path.stem
        with open(path) as f:
            for c in json.load(f):
                c["pr_number"] = int(pr_number)
                comments[c["id"]] = c
    return comments


def _load_rules(data_dir: Path) -> dict[int, dict]:
    rules = {}
    path = data_dir / "4-dedupe" / "rules.jsonl"
    if path.exists():
        with open(path) as f:
            for line in f:
                if line.strip():
                    r = json.loads(line)
                    rules[r["rule_id"]] = r
    return rules


def _load_placements(data_dir: Path) -> dict[int, dict]:
    placements = {}
    path = data_dir / "5-place" / "placements.jsonl"
    if path.exists():
        with open(path) as f:
            for line in f:
                if line.strip():
                    p = json.loads(line)
                    placements[p["rule_id"]] = p
    return placements


def _load_organization(data_dir: Path) -> dict:
    path = data_dir / "6-group" / "organized_rules.json"
    if path.exists():
        with open(path) as f:
            return json.load(f)
    return {"locations": []}


# ============================================================================
# Lookup Functions
# ============================================================================


def _find_rule_location(rule_id: int, organization: dict) -> dict | None:
    for loc_data in organization["locations"]:
        location = loc_data["location"]
        if rule_id in loc_data.get("inline_rules", []):
            return {"location": location, "type": "inline"}
        for topic in loc_data.get("topic_references", []):
            if rule_id in topic.get("rule_ids", []):
                return {
                    "location": location,
                    "type": "topic",
                    "topic_id": topic["topic_id"],
                    "topic_name": topic["topic_name"],
                }
    return None


def _lookup_rule(rule_id: int, data_dir: Path, verbose: bool = False) -> None:
    rules = _load_rules(data_dir)
    placements = _load_placements(data_dir)
    comments = _load_comments(data_dir)
    organization = _load_organization(data_dir)

    if rule_id not in rules:
        print(f"Rule {rule_id} not found")
        return

    rule = rules[rule_id]
    placement = placements.get(rule_id, {})
    org_location = _find_rule_location(rule_id, organization)

    print(f"\n{'=' * 70}")
    print(f"RULE {rule_id}")
    print(f"{'=' * 70}")
    print(f"\n{rule['text'][:200]}{'...' if len(rule['text']) > 200 else ''}")

    print("\n--- Metadata ---")
    print(f"Category: {rule.get('category', 'unknown')}")
    print(f"Scope: {rule.get('scope', 'unknown')}")
    print(f"Confidence: {rule.get('confidence', 0):.2f}")

    if placement:
        p = placement.get("placement", {})
        print("\n--- Placement (Stage 3) ---")
        print(f"Type: {p.get('placement_type', 'unknown')}")
        print(f"Timing: {p.get('timing', 'unknown')}")
        print(f"Abstraction: {p.get('abstraction', 'unknown')}")
        if p.get("directory"):
            print(f"Directory: {p['directory']}")
        if p.get("file_path"):
            print(f"File: {p['file_path']}")
        if p.get("target_element"):
            print(f"Element: {p['target_element']}")
        print(f"Rule Score: {placement.get('rule_score', placement.get('signal_score', 0)):.2f}")
        print(f"PRs: {placement.get('unique_pr_count', 0)}")

        if verbose and p.get("rationale"):
            print(f"\nRationale: {p['rationale'][:500]}...")

    if org_location:
        print("\n--- Final Location (Stage 4) ---")
        print(f"Location: {org_location['location']}")
        print(f"Type: {org_location['type']}")
        if org_location.get("topic_id"):
            print(f"Topic: {org_location['topic_name']} ({org_location['topic_id']})")

    source_comment_ids = rule.get("source_comments", [])
    source_prs = rule.get("source_prs", [])

    print("\n--- Source Evidence ---")
    print(f"PRs: {len(source_prs)} - {source_prs[:10]}{'...' if len(source_prs) > 10 else ''}")
    print(f"Comments: {len(source_comment_ids)}")

    if verbose and comments:
        print("\n--- Source Comments ---")
        for i, cid in enumerate(source_comment_ids[:5]):
            if cid in comments:
                c = comments[cid]
                user = c.get("user", {}).get("login", "?")
                print(f"\n[{i + 1}] PR #{c.get('pr_number', '?')} by @{user}")
                path = c.get("path", "")
                if path:
                    print(f"    {path}")
                diff_hunk = c.get("diff_hunk", "")
                if diff_hunk:
                    # Show last few lines of the diff hunk for context
                    lines = diff_hunk.strip().splitlines()
                    context_lines = lines[-8:] if len(lines) > 8 else lines
                    if len(lines) > 8:
                        context_lines = ["..."] + context_lines
                    indented = "\n    ".join(context_lines)
                    print(f"    {indented}")
                body = c.get("body", "")
                if body:
                    truncated = body[:300] + ("..." if len(body) > 300 else "")
                    indented = truncated.replace("\n", "\n    > ")
                    print(f"\n    > {indented}")
        if len(source_comment_ids) > 5:
            print(f"\n    ... and {len(source_comment_ids) - 5} more comments")

    print()


def _search_rules(query: str, data_dir: Path) -> None:
    rules = _load_rules(data_dir)
    placements = _load_placements(data_dir)

    query_lower = query.lower()
    matches = [
        (rid, rule) for rid, rule in rules.items() if query_lower in rule.get("text", "").lower()
    ]

    if not matches:
        print(f"No rules found matching '{query}'")
        return

    print(f"\nFound {len(matches)} rules matching '{query}':\n")
    for rid, rule in matches[:20]:
        p = placements.get(rid, {})
        score = p.get("rule_score", p.get("signal_score", 0))
        prs = p.get("unique_pr_count", 0)
        text = rule["text"][:80]
        print(f"  [{rid:3}] (score={score:.2f}, prs={prs}) {text}...")
    if len(matches) > 20:
        print(f"\n  ... and {len(matches) - 20} more")


def _list_rules_by_location(location: str, data_dir: Path) -> None:
    organization = _load_organization(data_dir)
    rules = _load_rules(data_dir)
    placements = _load_placements(data_dir)

    for loc_data in organization["locations"]:
        if loc_data["location"] == location:
            print(f"\n{'=' * 70}")
            print(f"RULES AT: {location}")
            print(f"{'=' * 70}")

            all_rule_ids = list(loc_data.get("inline_rules", []))
            for topic in loc_data.get("topic_references", []):
                all_rule_ids.extend(topic.get("rule_ids", []))

            for rid in sorted(set(all_rule_ids)):
                if rid in rules:
                    rule = rules[rid]
                    p = placements.get(rid, {})
                    score = p.get("rule_score", p.get("signal_score", 0))
                    text = rule["text"][:60]
                    print(f"  [{rid:3}] (score={score:.2f}) {text}...")
            return

    print(f"Location '{location}' not found")


# ============================================================================
# CLI Command
# ============================================================================


def lookup(
    ctx: typer.Context,
    rule_id: int | None = typer.Argument(None, help="Rule ID to look up"),
    verbose: bool = typer.Option(False, "--verbose", "-v", help="Show full details"),
    search: str | None = typer.Option(None, "--search", "-s", help="Search rules by text"),
    location: str | None = typer.Option(None, "--location", "-l", help="List rules at a location"),
) -> None:
    """Trace rules back to source PRs."""
    config: RepoConfig = ctx.obj["config"]
    data_dir = config.data_dir

    if search:
        _search_rules(search, data_dir)
    elif location:
        _list_rules_by_location(location, data_dir)
    elif rule_id is not None:
        _lookup_rule(rule_id, data_dir, verbose)
    else:
        typer.echo("Provide a rule_id, --search, or --location")
        raise typer.Exit(1)


def _run(config: RepoConfig, **kwargs) -> None:
    """Programmatic entry point (not used by pipeline, but kept for consistency)."""
    pass
